json_num <- function(x) {
  paste0("[", paste(sprintf("%.17g", as.numeric(x)), collapse = ","), "]")
}
json_str <- function(s) {
  s <- gsub("\\", "\\\\", s, fixed = TRUE)
  s <- gsub("\"", "\\\"", s, fixed = TRUE)
  paste0("\"", s, "\"")
}
json_msgs <- function(lines) {
  if (length(lines) == 0) return("[]")
  paste0("[", paste(vapply(lines, json_str, ""), collapse = ","), "]")
}

